1	import { useState } from 'react';
2	import { supabase } from '../lib/supabase';
3	import { useToast } from '../contexts/ToastContext';
4	import { logError, logWarn } from '../lib/logger';
5	
6	export function useJobApplication() {
7	    const [applyingId, setApplyingId] = useState<string | null>(null);
8	    const { addToast } = useToast();
9	
10	    const applyForJob = async (jobId: string, onSuccess?: () => void) => {
11	        const { data: { user } } = await supabase.auth.getUser();
12	        if (!user) {
13	            addToast('Você precisa estar logado para se candidatar.', 'error');
14	            return;
15	        }
16	
17	        // 0. Check if profile exists (to give better error message than RLS/Foreign Key)
18	        const { data: profile } = await supabase
19	            .from('workers')
20	            .select('id')
21	            .eq('id', user.id)
22	            .maybeSingle();
23	
24	        if (!profile) {
25	            addToast('Complete seu perfil antes de se candidatar.', 'error');
26	            // Optionally redirect to onboarding?
27	            return;
28	        }
29	
30	        setApplyingId(jobId);
31	
32	        try {
33	            // 1. Check if already applied (Double safety, though UI should handle this)
34	            const { data: existing, error: checkError } = await supabase
35	                .from('applications')
36	                .select('id')
37	                .eq('job_id', jobId)
38	                .eq('worker_id', user.id)
39	                .maybeSingle();
40	
41	            if (checkError) {
42	                // If 403, it might mean RLS blocks reading.
43	                // We proceed to try insert, as insert policy might allow different things than select policy
44	                // depending on configuration. But usually if select fails, we shouldn't block blindly.
45	                // However, let's assume if it errors, we just try to apply.
46	                logWarn('Check application error (RLS?)', checkError.message);
47	            }
48	
49	            if (existing) {
50	                addToast('Você já se candidatou a esta vaga!', 'info');
51	                if (onSuccess) onSuccess();
52	                return;
53	            }
54	
55	            // 2. Insert Application
56	            const { data, error } = await supabase
57	                .from('applications')
58	                .insert({
59	                    job_id: jobId,
60	                    worker_id: user.id,
61	                    status: 'pending'
62	                })
63	                .select()
64	                .single();
65	
66	            if (error) {
67	                // Handle Specific RLS or Constraint errors
68	                if (error.code === '42501') { // Postgres RLS Policy Violation
69	                    throw new Error('Permissão negada. Verifique se seu perfil está completo.');
70	                }
71	                if (error.code === '23505') { // Unique Violation
72	                    addToast('Você já se candidatou a esta vaga.', 'info');
73	                    if (onSuccess) onSuccess();
74	                    return;
75	                }
76	                throw error;
77	            }
78	
79	            // 3. Create Conversation for this application (only if doesn't exist)
80	            if (data) {
81	                // First check if conversation already exists to prevent duplicates
82	                const { data: existingConv } = await supabase
83	                    .from('Conversation')
84	                    .select('id')
85	                    .eq('application_uuid', data.id)
86	                    .maybeSingle();
87	
88	                if (!existingConv) {
89	                    const { error: convError } = await supabase
90	                        .from('Conversation')
91	                        .insert({
92	                            id: crypto.randomUUID(),
93	                            application_uuid: data.id,
94	                            createdat: new Date().toISOString(),
95	                            islocked: false
96	                        });
97	
98	                    if (convError) {
99	                        logError('Error creating conversation', convError);
100	                    }
101	                }
102	            }
103	
104	            addToast('Candidatura enviada com sucesso! Boa sorte!', 'success');
105	            if (onSuccess) onSuccess();
106	
107	        } catch (err: unknown) {
108	            logError('Error applying', err);
109	
110	            const message = err instanceof Error ? err.message : 'Ocorreu um erro ao aplicar. Tente novamente.';
111	
112	            // Avoid "Object" or generic messages if possible
113	            if (message.includes('JSON')) {
114	                addToast('Erro de conexão. Tente novamente.', 'error');
115	            } else {
116	                addToast(message, 'error');
117	            }
118	
119	        } finally {
120	            setApplyingId(null);
121	        }
122	    };
123	
124	    return {
125	        applyingId,
126	        applyForJob
127	    };
128	}
