/**
 * TeamConnectionService — gerencia o roster "minha equipe" (Slice 1, R1/R2).
 *
 * Modelo: aresta bilateral consentida (handshake UMA vez).
 * - Empresa adiciona o freela via QR / link / telefone → conexão nasce 'pending'.
 * - Freela aceita → 'accepted'. Convites de turno seguintes NÃO re-pedem handshake.
 * - Freela pode sair/bloquear → 'blocked'.
 *
 * Avisos do architect (ADR-001):
 * - Criar-turno e aceite NÃO chamam reserve_escrow (postpago é Slice 2).
 * - A empresa NÃO pode forjar 'accepted' (RLS WITH CHECK).
 * - Envio de SMS para o canal 'phone' é Slice 4 — aqui só criamos o registro.
 */

import { supabase } from '../lib/supabase';
import { logError } from '../lib/logger';
import type {
  TeamConnection,
  TeamConnectionSource,
  TeamConnectionStatus,
  TeamMember,
  MyStore,
  WorkerProfile,
  CompanyProfile,
} from '../types';

// ---------------------------------------------------------------------------
// Tipos auxiliares internos
// ---------------------------------------------------------------------------

export interface CreateConnectionResult {
  connection: TeamConnection | null;
  error?: string;
  /** true quando a conexão já existia (idempotência de convite de equipe) */
  alreadyExists?: boolean;
}

export interface UpdateConnectionResult {
  success: boolean;
  error?: string;
}

/**
 * Token de convite de conexão via link (R1-b).
 * Gerado pelo service e armazenado como metadata na conexão.
 * Resolução: o link traz o token → service lê a conexão pending → worker aceita.
 */
export interface ConnectionInviteToken {
  token: string;
  /** URL pública do link de convite */
  url: string;
}

// ---------------------------------------------------------------------------
// Helpers de query de empresa (session)
// ---------------------------------------------------------------------------

/**
 * Retorna o `company_id` da empresa autenticada.
 * Lança erro se não houver sessão ou se o usuário não for empresa.
 */
async function getAuthenticatedCompanyId(): Promise<string> {
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) throw new Error('Sessão expirada. Faça login novamente.');

  const { data: company, error } = await supabase
    .from('companies')
    .select('id')
    .eq('owner_id', user.id)
    .maybeSingle();

  if (error) throw error;
  if (!company) throw new Error('Perfil de empresa não encontrado.');

  return company.id as string;
}

// ---------------------------------------------------------------------------
// TeamConnectionService
// ---------------------------------------------------------------------------

export const TeamConnectionService = {
  // -------------------------------------------------------------------------
  // EMPRESA: adicionar freela à equipe
  // -------------------------------------------------------------------------

  /**
   * Adiciona um worker ao roster da empresa (cria conexão 'pending').
   *
   * @param workerId  UUID do worker (a câmera/scan é responsabilidade da UI).
   * @param source    Canal de origem: 'qr' | 'link' | 'phone'.
   *
   * Canal 'phone': cria o registro pending; o envio de SMS é Slice 4 (NÃO chamado aqui).
   * Canal 'link':  gera um token estável; use `generateInviteToken()` para obter a URL.
   * Canal 'qr':    a UI fornece o workerId após decode do QR; apenas cria a conexão.
   *
   * Idempotente: se a conexão já existir retorna `alreadyExists: true` sem erro.
   */
  async addToTeam(
    workerId: string,
    source: TeamConnectionSource,
  ): Promise<CreateConnectionResult> {
    try {
      const companyId = await getAuthenticatedCompanyId();

      // Verificar se já existe (idempotência — UNIQUE team_connections_unique_pair)
      const { data: existing, error: checkErr } = await supabase
        .from('team_connections')
        .select('*')
        .eq('company_id', companyId)
        .eq('worker_id', workerId)
        .maybeSingle();

      if (checkErr) {
        logError('teamConnection.addToTeam.check', checkErr);
        return { connection: null, error: 'Erro ao verificar conexão existente.' };
      }

      if (existing) {
        return {
          connection: existing as TeamConnection,
          alreadyExists: true,
        };
      }

      const { data, error } = await supabase
        .from('team_connections')
        .insert({
          company_id: companyId,
          worker_id: workerId,
          status: 'pending' as TeamConnectionStatus,
          source,
        })
        .select()
        .single();

      if (error) {
        // Corrida: insert concorrente pode ter criado antes de nós (race condition)
        if (error.code === '23505') {
          return { connection: null, alreadyExists: true };
        }
        logError('teamConnection.addToTeam.insert', error);
        return { connection: null, error: 'Não foi possível adicionar o freela à equipe.' };
      }

      return { connection: data as TeamConnection };
    } catch (err) {
      logError('teamConnection.addToTeam', err);
      return {
        connection: null,
        error: err instanceof Error ? err.message : 'Erro inesperado.',
      };
    }
  },

  /**
   * Gera (ou reutiliza) um token de convite de link para a empresa atual.
   *
   * Estratégia: o token é o `company_id` codificado em base64url + timestamp truncado,
   * suficiente para o MVP (não requer tabela separada de tokens).
   * A UI monta a URL: `https://app.worki.com/convite/{token}`.
   * O resolver do link chama `resolveInviteToken(token)` para descobrir a empresa.
   */
  generateInviteToken(companyId: string): ConnectionInviteToken {
    // Token simples, não criptográfico — o RLS protege o DB; o token só identifica a empresa.
    const payload = `${companyId}:${Date.now()}`;
    const token = btoa(payload).replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
    const url = `${window.location.origin}/convite/${token}`;
    return { token, url };
  },

  /**
   * Resolve um token de link de convite → retorna o `company_id`.
   * Retorna null se o token for inválido ou malformado.
   */
  resolveInviteToken(token: string): string | null {
    try {
      const padded = token.replace(/-/g, '+').replace(/_/g, '/');
      const payload = atob(padded);
      const [companyId] = payload.split(':');
      if (!companyId || companyId.length < 30) return null;
      return companyId;
    } catch {
      return null;
    }
  },

  /**
   * Adiciona um worker via token de link de convite.
   * A empresa é extraída do token; o worker aceita a conexão no próximo passo.
   */
  async addToTeamByToken(
    token: string,
    workerId: string,
  ): Promise<CreateConnectionResult> {
    const companyId = this.resolveInviteToken(token);
    if (!companyId) {
      return { connection: null, error: 'Link de convite inválido ou expirado.' };
    }

    // Inserir a conexão diretamente (o worker dispara isso via link)
    // O RLS de INSERT exige que company_id IN companies WHERE owner_id = auth.uid().
    // Aqui o worker não é dono da company → não pode usar a policy de empresa.
    // Solução: o link de convite é resolvido pela EMPRESA (ela abre o link no seu contexto)
    // OU a inserção usa invokeFunction para uma Edge Function se precisarmos do worker-side.
    // Para o MVP, o fluxo de link abre na sessão da empresa → addToTeam normal.
    // Se o fluxo for "worker clica no link" → vira uma pending da empresa pendente de iniciativa.
    // No MVP v1, o link é enviado pela empresa para o worker fora do app; o worker aceita depois.
    // Registro da conexão: a empresa cria pending via addToTeam; o worker aceita via acceptConnection.
    // Esta função é um helper de conveniência para testes e fluxos alternativos.
    const { data: company, error: cErr } = await supabase
      .from('companies')
      .select('id, owner_id')
      .eq('id', companyId)
      .single();

    if (cErr || !company) {
      return { connection: null, error: 'Empresa do convite não encontrada.' };
    }

    // Verificar existência
    const { data: existing } = await supabase
      .from('team_connections')
      .select('*')
      .eq('company_id', companyId)
      .eq('worker_id', workerId)
      .maybeSingle();

    if (existing) {
      return { connection: existing as TeamConnection, alreadyExists: true };
    }

    const { data, error } = await supabase
      .from('team_connections')
      .insert({
        company_id: companyId,
        worker_id: workerId,
        status: 'pending' as TeamConnectionStatus,
        source: 'link' as TeamConnectionSource,
      })
      .select()
      .single();

    if (error) {
      if (error.code === '23505') {
        return { connection: null, alreadyExists: true };
      }
      logError('teamConnection.addToTeamByToken.insert', error);
      return { connection: null, error: 'Não foi possível registrar o convite.' };
    }

    return { connection: data as TeamConnection };
  },

  // -------------------------------------------------------------------------
  // WORKER: aceitar ou bloquear/sair
  // -------------------------------------------------------------------------

  /**
   * Worker aceita uma conexão pendente (pending → accepted).
   * Máquina de estados validada aqui: só aceita se status for 'pending'.
   */
  async acceptConnection(connectionId: string): Promise<UpdateConnectionResult> {
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) return { success: false, error: 'Sessão expirada.' };

      // Validar estado atual (máquina de estados no service — ADR-001)
      const { data: current, error: fetchErr } = await supabase
        .from('team_connections')
        .select('id, status, worker_id')
        .eq('id', connectionId)
        .maybeSingle();

      if (fetchErr) {
        logError('teamConnection.acceptConnection.fetch', fetchErr);
        return { success: false, error: 'Conexão não encontrada.' };
      }
      if (!current) return { success: false, error: 'Conexão não encontrada.' };
      if (current.worker_id !== user.id) {
        return { success: false, error: 'Você não é o freela desta conexão.' };
      }
      if (current.status !== 'pending') {
        return {
          success: false,
          error: `Transição inválida: status atual é '${current.status}', esperado 'pending'.`,
        };
      }

      const { error } = await supabase
        .from('team_connections')
        .update({
          status: 'accepted' as TeamConnectionStatus,
          accepted_at: new Date().toISOString(),
        })
        .eq('id', connectionId)
        .eq('worker_id', user.id);

      if (error) {
        logError('teamConnection.acceptConnection.update', error);
        return { success: false, error: 'Erro ao aceitar conexão.' };
      }

      return { success: true };
    } catch (err) {
      logError('teamConnection.acceptConnection', err);
      return {
        success: false,
        error: err instanceof Error ? err.message : 'Erro inesperado.',
      };
    }
  },

  /**
   * Worker sai/bloqueia uma empresa (→ 'blocked').
   * Funciona para status 'pending' (recusar convite de equipe) ou 'accepted' (sair).
   */
  async blockConnection(connectionId: string): Promise<UpdateConnectionResult> {
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) return { success: false, error: 'Sessão expirada.' };

      // Validar propriedade (deve ser o worker da conexão)
      const { data: current, error: fetchErr } = await supabase
        .from('team_connections')
        .select('id, status, worker_id')
        .eq('id', connectionId)
        .maybeSingle();

      if (fetchErr || !current) {
        logError('teamConnection.blockConnection.fetch', fetchErr);
        return { success: false, error: 'Conexão não encontrada.' };
      }
      if (current.worker_id !== user.id) {
        return { success: false, error: 'Você não é o freela desta conexão.' };
      }
      if (current.status === 'blocked') {
        return { success: true }; // já bloqueada — idempotente
      }

      const { error } = await supabase
        .from('team_connections')
        .update({
          status: 'blocked' as TeamConnectionStatus,
          blocked_by: user.id,
        })
        .eq('id', connectionId)
        .eq('worker_id', user.id);

      if (error) {
        logError('teamConnection.blockConnection.update', error);
        return { success: false, error: 'Erro ao bloquear conexão.' };
      }

      return { success: true };
    } catch (err) {
      logError('teamConnection.blockConnection', err);
      return {
        success: false,
        error: err instanceof Error ? err.message : 'Erro inesperado.',
      };
    }
  },

  // -------------------------------------------------------------------------
  // EMPRESA: listar equipe aceita ("minha equipe")
  // -------------------------------------------------------------------------

  /**
   * Lista os membros aceitos da equipe da empresa autenticada.
   * Retorna conexões 'accepted' com perfil do worker embutido.
   */
  async listTeamMembers(): Promise<TeamMember[]> {
    try {
      const companyId = await getAuthenticatedCompanyId();

      const { data, error } = await supabase
        .from('team_connections')
        .select(
          `
          *,
          worker:workers (
            id,
            full_name,
            avatar_url,
            photo_url,
            primary_role,
            roles,
            rating_average,
            reviews_count,
            completed_jobs_count,
            phone,
            city
          )
        `,
        )
        .eq('company_id', companyId)
        .eq('status', 'accepted')
        .order('accepted_at', { ascending: false });

      if (error) {
        logError('teamConnection.listTeamMembers', error);
        return [];
      }

      return ((data ?? []) as Array<TeamConnection & { worker: WorkerProfile }>).map(
        (row) => ({
          connection: {
            id: row.id,
            company_id: row.company_id,
            worker_id: row.worker_id,
            status: row.status,
            source: row.source,
            blocked_by: row.blocked_by,
            created_at: row.created_at,
            accepted_at: row.accepted_at,
            updated_at: row.updated_at,
          },
          worker: row.worker,
        }),
      );
    } catch (err) {
      logError('teamConnection.listTeamMembers', err);
      return [];
    }
  },

  /**
   * Lista todas as conexões da empresa (pending + accepted + blocked).
   * Útil para a UI de gestão da equipe.
   */
  async listAllConnections(): Promise<TeamConnection[]> {
    try {
      const companyId = await getAuthenticatedCompanyId();

      const { data, error } = await supabase
        .from('team_connections')
        .select(
          `
          *,
          worker:workers (
            id,
            full_name,
            avatar_url,
            photo_url,
            primary_role,
            rating_average,
            phone,
            city
          )
        `,
        )
        .eq('company_id', companyId)
        .order('created_at', { ascending: false });

      if (error) {
        logError('teamConnection.listAllConnections', error);
        return [];
      }

      return (data ?? []) as TeamConnection[];
    } catch (err) {
      logError('teamConnection.listAllConnections', err);
      return [];
    }
  },

  // -------------------------------------------------------------------------
  // WORKER: listar "minhas lojas"
  // -------------------------------------------------------------------------

  /**
   * Lista as conexões aceitas do worker autenticado ("minhas lojas").
   * Retorna conexões 'accepted' com perfil da empresa embutido.
   */
  async listMyStores(): Promise<MyStore[]> {
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) return [];

      const { data, error } = await supabase
        .from('team_connections')
        .select(
          `
          *,
          company:companies (
            id,
            name,
            logo_url,
            rating_average,
            reviews_count,
            industry,
            address
          )
        `,
        )
        .eq('worker_id', user.id)
        .eq('status', 'accepted')
        .order('accepted_at', { ascending: false });

      if (error) {
        logError('teamConnection.listMyStores', error);
        return [];
      }

      return ((data ?? []) as Array<TeamConnection & { company: CompanyProfile }>).map(
        (row) => ({
          connection: {
            id: row.id,
            company_id: row.company_id,
            worker_id: row.worker_id,
            status: row.status,
            source: row.source,
            blocked_by: row.blocked_by,
            created_at: row.created_at,
            accepted_at: row.accepted_at,
            updated_at: row.updated_at,
          },
          company: row.company,
        }),
      );
    } catch (err) {
      logError('teamConnection.listMyStores', err);
      return [];
    }
  },

  /**
   * Lista conexões pendentes (convites de equipe) do worker autenticado.
   * Para a UI do worker aceitar/recusar convites de equipe.
   */
  async listPendingConnections(): Promise<TeamConnection[]> {
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) return [];

      const { data, error } = await supabase
        .from('team_connections')
        .select(
          `
          *,
          company:companies (
            id,
            name,
            logo_url,
            rating_average,
            industry,
            address
          )
        `,
        )
        .eq('worker_id', user.id)
        .eq('status', 'pending')
        .order('created_at', { ascending: false });

      if (error) {
        logError('teamConnection.listPendingConnections', error);
        return [];
      }

      return (data ?? []) as TeamConnection[];
    } catch (err) {
      logError('teamConnection.listPendingConnections', err);
      return [];
    }
  },

  // -------------------------------------------------------------------------
  // Validação: checar se um worker é da equipe aceita de uma empresa
  // -------------------------------------------------------------------------

  /**
   * Retorna true se o worker for conexão 'accepted' da empresa.
   * Usado antes de criar um convite de turno (R5/ADR-001).
   */
  async isWorkerInTeam(companyId: string, workerId: string): Promise<boolean> {
    const { data, error } = await supabase
      .from('team_connections')
      .select('id')
      .eq('company_id', companyId)
      .eq('worker_id', workerId)
      .eq('status', 'accepted')
      .maybeSingle();

    if (error) {
      logError('teamConnection.isWorkerInTeam', error);
      return false;
    }

    return !!data;
  },
};

/**
 * ShiftInviteService — convite push de turno (Slice 1, R5/R7/R8).
 *
 * Fluxo push: EMPRESA cria application com status='invited' para worker da equipe.
 * Fluxo de resposta: WORKER aceita ('accepted') ou recusa ('declined').
 *
 * Avisos do architect (ADR-001):
 * 1. A transição de status do convite (invited → accepted/declined) NÃO é forçada por RLS;
 *    validamos a máquina de estados AQUI no service.
 * 2. Recusa é NEUTRA (zero punição — R7): só muda status para 'declined'.
 * 3. Criar-turno e aceite NÃO chamam reserve_escrow (postpago é Slice 2).
 *    accepted aqui = status 'hired' (confirmado no turno) SEM escrow. Slice 2 preenche o gap.
 * 4. inserts de review devem passar direction explicitamente — ver ReviewService em types/index.ts.
 */

import { supabase } from '../lib/supabase';
import { invokeFunction } from './api';
import { logError } from '../lib/logger';
import { TeamConnectionService } from './teamConnectionService';
import type {
  Application,
  ApplicationStatus,
  InvitationResponse,
} from '../types';

// ---------------------------------------------------------------------------
// Tipos de parâmetros e resultado
// ---------------------------------------------------------------------------

/** Janela de expiração do convite em horas (R8). Default = 48h. */
const DEFAULT_INVITE_EXPIRY_HOURS = 48;

export interface InviteWorkerToShiftOptions {
  /** Horas até o convite expirar (default: 48). */
  expiresInHours?: number;
  /** Mensagem personalizada para a notificação (opcional). */
  message?: string;
}

export interface InviteWorkerResult {
  application: Application | null;
  error?: string;
  /** true quando já existe um convite pendente (idempotência). */
  alreadyInvited?: boolean;
}

export interface RespondToInviteResult {
  success: boolean;
  error?: string;
}

// ---------------------------------------------------------------------------
// Helpers internos
// ---------------------------------------------------------------------------

/** Obtém o company_id da sessão autenticada (empresa). */
async function getAuthCompanyId(): Promise<string> {
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) throw new Error('Sessão expirada. Faça login novamente.');

  const { data: company, error } = await supabase
    .from('companies')
    .select('id')
    .eq('owner_id', user.id)
    .maybeSingle();

  if (error) throw error;
  if (!company) throw new Error('Perfil de empresa não encontrado.');

  return company.id as string;
}

/** Calcula timestamp de expiração. */
function calcExpiry(hours: number): string {
  const d = new Date();
  d.setHours(d.getHours() + hours);
  return d.toISOString();
}

// ---------------------------------------------------------------------------
// ShiftInviteService
// ---------------------------------------------------------------------------

export const ShiftInviteService = {
  // -------------------------------------------------------------------------
  // EMPRESA: convidar worker para turno
  // -------------------------------------------------------------------------

  /**
   * Convida um worker da equipe para um turno específico.
   *
   * Pré-condições verificadas:
   *  1. O worker é conexão 'accepted' da empresa (R2 — lista fechada).
   *  2. Não existe convite ativo (invited) para o mesmo job+worker.
   *
   * Ações:
   *  1. Insere em `applications` com status='invited'.
   *  2. Cria notificação in-app (insert em `notifications`).
   *  3. Invoca `send-notification` para entrega por e-mail.
   *
   * Não chama reserve_escrow (Slice 2).
   *
   * @param jobId    UUID do turno (job).
   * @param workerId UUID do worker a convidar.
   * @param opts     Opções adicionais.
   */
  async inviteWorkerToShift(
    jobId: string,
    workerId: string,
    opts: InviteWorkerToShiftOptions = {},
  ): Promise<InviteWorkerResult> {
    try {
      const companyId = await getAuthCompanyId();

      // 1. Validar que o worker está na equipe aceita (R2)
      const inTeam = await TeamConnectionService.isWorkerInTeam(companyId, workerId);
      if (!inTeam) {
        return {
          application: null,
          error:
            'O freela não está na sua equipe. Adicione-o primeiro para poder convidar.',
        };
      }

      // 2. Verificar se já existe convite pendente (idempotência)
      const { data: existing, error: checkErr } = await supabase
        .from('applications')
        .select('id, status')
        .eq('job_id', jobId)
        .eq('worker_id', workerId)
        .maybeSingle();

      if (checkErr) {
        logError('shiftInvite.inviteWorkerToShift.check', checkErr);
        return { application: null, error: 'Erro ao verificar convite existente.' };
      }

      if (existing) {
        // Já existe application (qualquer status)
        if (existing.status === 'invited') {
          return {
            application: existing as Application,
            alreadyInvited: true,
          };
        }
        return {
          application: null,
          error: `Já existe uma candidatura para este turno com status '${existing.status}'.`,
        };
      }

      // 3. Calcular expiração
      const expiresInHours = opts.expiresInHours ?? DEFAULT_INVITE_EXPIRY_HOURS;
      const expiresAt = calcExpiry(expiresInHours);
      const now = new Date().toISOString();

      // 4. Inserir convite em applications
      const { data: application, error: insertErr } = await supabase
        .from('applications')
        .insert({
          job_id: jobId,
          worker_id: workerId,
          status: 'invited' as ApplicationStatus,
          invited_by_company_at: now,
          invitation_expires_at: expiresAt,
        })
        .select()
        .single();

      if (insertErr) {
        if (insertErr.code === '23505') {
          return { application: null, alreadyInvited: true };
        }
        logError('shiftInvite.inviteWorkerToShift.insert', insertErr);
        return { application: null, error: 'Não foi possível criar o convite.' };
      }

      // 5. Notificação in-app (insert direto em notifications)
      const { error: notifErr } = await supabase.from('notifications').insert({
        user_id: workerId,
        type: 'status_change',
        title: 'Novo convite de turno',
        message:
          opts.message ??
          'Você recebeu um convite para um turno. Acesse "Convites" para aceitar ou recusar.',
        link: `/meus-trabalhos?tab=convites`,
      });

      if (notifErr) {
        // Não bloqueia — a application foi criada; notificação é best-effort
        logError('shiftInvite.inviteWorkerToShift.notif', notifErr);
      }

      // 6. Entrega por e-mail via send-notification (best-effort)
      try {
        await invokeFunction('send-notification', {
          userId: workerId,
          type: 'shift_invite',
          data: {
            jobId,
            applicationId: application.id,
            expiresAt,
          },
        });
      } catch (emailErr) {
        // Edge function falhou — não bloqueia o convite
        logError('shiftInvite.inviteWorkerToShift.email', emailErr);
      }

      return { application: application as Application };
    } catch (err) {
      logError('shiftInvite.inviteWorkerToShift', err);
      return {
        application: null,
        error: err instanceof Error ? err.message : 'Erro inesperado.',
      };
    }
  },

  // -------------------------------------------------------------------------
  // WORKER: responder ao convite (aceitar ou recusar)
  // -------------------------------------------------------------------------

  /**
   * Worker responde a um convite de turno.
   *
   * Máquina de estados (validada aqui — ADR-001):
   *   'invited' → 'hired'    (quando accepted)
   *   'invited' → 'declined' (quando declined — NEUTRO, zero punição — R7)
   *
   * NÃO chama reserve_escrow (postpago é Slice 2; Slice 2 adiciona o hook aqui).
   *
   * @param applicationId UUID da application (convite).
   * @param response      'accepted' | 'declined'.
   */
  async respondToInvite(
    applicationId: string,
    response: InvitationResponse,
  ): Promise<RespondToInviteResult> {
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) return { success: false, error: 'Sessão expirada.' };

      // 1. Buscar application atual (validar máquina de estados)
      const { data: current, error: fetchErr } = await supabase
        .from('applications')
        .select('id, status, worker_id, invited_by_company_at, invitation_expires_at')
        .eq('id', applicationId)
        .maybeSingle();

      if (fetchErr) {
        logError('shiftInvite.respondToInvite.fetch', fetchErr);
        return { success: false, error: 'Convite não encontrado.' };
      }
      if (!current) return { success: false, error: 'Convite não encontrado.' };
      if (current.worker_id !== user.id) {
        return { success: false, error: 'Este convite não é para você.' };
      }
      if (current.status !== 'invited') {
        return {
          success: false,
          error: `Transição inválida: status atual é '${current.status}', esperado 'invited'.`,
        };
      }

      // 2. Verificar expiração (R8)
      if (current.invitation_expires_at) {
        const expiresAt = new Date(current.invitation_expires_at as string);
        if (expiresAt < new Date()) {
          return {
            success: false,
            error: 'Este convite expirou. O operador precisará reenviar um novo convite.',
          };
        }
      }

      // 3. Mapear response → status final
      //    accepted → 'hired' (turno confirmado para os dois lados — sem escrow neste slice)
      //    declined → 'declined' (neutro — R7)
      const newStatus: ApplicationStatus = response === 'accepted' ? 'hired' : 'declined';
      const now = new Date().toISOString();

      const { error: updateErr } = await supabase
        .from('applications')
        .update({
          status: newStatus,
          invitation_response: response,
          invitation_responded_at: now,
        })
        .eq('id', applicationId)
        .eq('worker_id', user.id);

      if (updateErr) {
        logError('shiftInvite.respondToInvite.update', updateErr);
        return { success: false, error: 'Erro ao registrar resposta.' };
      }

      // 4. Notificação in-app para a empresa (best-effort)
      if (response === 'accepted') {
        // Buscar company para notificar o operador
        const { data: job } = await supabase
          .from('applications')
          .select('job:jobs(company_id)')
          .eq('id', applicationId)
          .maybeSingle();

        // job.job é um objeto com company_id
        const companyId = (job?.job as { company_id?: string } | null)?.company_id;

        if (companyId) {
          // Buscar owner da empresa
          const { data: company } = await supabase
            .from('companies')
            .select('owner_id')
            .eq('id', companyId)
            .maybeSingle();

          if (company?.owner_id) {
            const { error: notifErr } = await supabase.from('notifications').insert({
              user_id: company.owner_id,
              type: 'status_change',
              title: 'Freela aceitou o turno',
              message: 'Um freela aceitou seu convite de turno.',
              link: `/company/candidates`,
            });

            if (notifErr) {
              logError('shiftInvite.respondToInvite.notif', notifErr);
            }
          }
        }
      }

      return { success: true };
    } catch (err) {
      logError('shiftInvite.respondToInvite', err);
      return {
        success: false,
        error: err instanceof Error ? err.message : 'Erro inesperado.',
      };
    }
  },

  // -------------------------------------------------------------------------
  // Listagem de convites pendentes (worker)
  // -------------------------------------------------------------------------

  /**
   * Lista convites de turno pendentes ('invited') do worker autenticado.
   * Inclui dados do job e da empresa para a aba "Convites".
   */
  async listPendingInvites(): Promise<Application[]> {
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) return [];

      const { data, error } = await supabase
        .from('applications')
        .select(
          `
          *,
          job:jobs (
            id,
            title,
            description,
            location,
            start_date,
            work_start_time,
            work_end_time,
            budget,
            has_lunch,
            company_id,
            company:companies (
              id,
              name,
              logo_url,
              rating_average
            )
          )
        `,
        )
        .eq('worker_id', user.id)
        .eq('status', 'invited')
        .order('invited_by_company_at', { ascending: false });

      if (error) {
        logError('shiftInvite.listPendingInvites', error);
        return [];
      }

      return (data ?? []) as Application[];
    } catch (err) {
      logError('shiftInvite.listPendingInvites', err);
      return [];
    }
  },

  /**
   * Lista convites enviados por uma empresa para um job específico.
   * Para o operador acompanhar respostas.
   */
  async listInvitesByJob(jobId: string): Promise<Application[]> {
    try {
      const { data, error } = await supabase
        .from('applications')
        .select(
          `
          *,
          worker:workers (
            id,
            full_name,
            avatar_url,
            photo_url,
            primary_role,
            rating_average,
            phone
          )
        `,
        )
        .eq('job_id', jobId)
        .not('invited_by_company_at', 'is', null)
        .order('invited_by_company_at', { ascending: false });

      if (error) {
        logError('shiftInvite.listInvitesByJob', error);
        return [];
      }

      return (data ?? []) as Application[];
    } catch (err) {
      logError('shiftInvite.listInvitesByJob', err);
      return [];
    }
  },
};

/**
 * useTeamConnections — hook de UI para o roster "minha equipe" e "minhas lojas".
 *
 * Dois modos de uso:
 *   - papel 'company': lista equipe aceita + conexões pendentes da empresa.
 *   - papel 'worker':  lista lojas aceitas + convites de equipe pendentes.
 *
 * Padrão do projeto: useState + useEffect + supabase direto (Art. 5 — sem React Query).
 */

import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../lib/supabase';
import { TeamConnectionService } from '../services/teamConnectionService';
import { useToast } from '../contexts/ToastContext';
import type { TeamConnection, TeamMember, MyStore, TeamConnectionSource } from '../types';

// ---------------------------------------------------------------------------
// Hook para EMPRESA — gerenciar "minha equipe"
// ---------------------------------------------------------------------------

export interface UseCompanyTeamResult {
  /** Membros aceitos (com perfil do worker). */
  teamMembers: TeamMember[];
  /** Convites de equipe pendentes (empresa enviou, aguarda worker). */
  pendingConnections: TeamConnection[];
  loading: boolean;
  /** Adicionar worker via QR/link/phone. */
  addWorker: (workerId: string, source: TeamConnectionSource) => Promise<boolean>;
  /** Recarregar dados. */
  refresh: () => void;
}

export function useCompanyTeam(): UseCompanyTeamResult {
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
  const [pendingConnections, setPendingConnections] = useState<TeamConnection[]>([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();
  const { addToast } = useToast();

  const load = useCallback(async () => {
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) {
      navigate('/login');
      return;
    }

    setLoading(true);
    const [members, all] = await Promise.all([
      TeamConnectionService.listTeamMembers(),
      TeamConnectionService.listAllConnections(),
    ]);

    setTeamMembers(members);
    setPendingConnections(all.filter((c) => c.status === 'pending'));
    setLoading(false);
  }, [navigate]);

  useEffect(() => {
    let active = true;
    void (async () => {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) {
        navigate('/login');
        return;
      }

      setLoading(true);
      const [members, all] = await Promise.all([
        TeamConnectionService.listTeamMembers(),
        TeamConnectionService.listAllConnections(),
      ]);

      if (!active) return;
      setTeamMembers(members);
      setPendingConnections(all.filter((c) => c.status === 'pending'));
      setLoading(false);
    })();
    return () => {
      active = false;
    };
  }, [navigate]);

  const addWorker = useCallback(
    async (workerId: string, source: TeamConnectionSource): Promise<boolean> => {
      const result = await TeamConnectionService.addToTeam(workerId, source);

      if (result.alreadyExists) {
        addToast('Este freela já está na sua equipe.', 'info');
        return true;
      }
      if (result.error) {
        addToast(result.error, 'error');
        return false;
      }

      addToast('Convite de equipe enviado! Aguardando aceite do freela.', 'success');
      load();
      return true;
    },
    [addToast, load],
  );

  return { teamMembers, pendingConnections, loading, addWorker, refresh: load };
}

// ---------------------------------------------------------------------------
// Hook para WORKER — "minhas lojas" + convites de equipe pendentes
// ---------------------------------------------------------------------------

export interface UseWorkerStoresResult {
  /** Empresas aceitas ("minhas lojas"). */
  myStores: MyStore[];
  /** Convites de equipe pendentes (empresa convidou, aguarda aceite do worker). */
  pendingConnections: TeamConnection[];
  loading: boolean;
  /** Aceitar convite de equipe. */
  acceptConnection: (connectionId: string) => Promise<boolean>;
  /** Bloquear/sair de uma empresa. */
  blockConnection: (connectionId: string) => Promise<boolean>;
  /** Recarregar dados. */
  refresh: () => void;
}

export function useWorkerStores(): UseWorkerStoresResult {
  const [myStores, setMyStores] = useState<MyStore[]>([]);
  const [pendingConnections, setPendingConnections] = useState<TeamConnection[]>([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();
  const { addToast } = useToast();

  const load = useCallback(async () => {
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) {
      navigate('/login');
      return;
    }

    setLoading(true);
    const [stores, pending] = await Promise.all([
      TeamConnectionService.listMyStores(),
      TeamConnectionService.listPendingConnections(),
    ]);

    setMyStores(stores);
    setPendingConnections(pending);
    setLoading(false);
  }, [navigate]);

  useEffect(() => {
    let active = true;
    void (async () => {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) {
        navigate('/login');
        return;
      }

      setLoading(true);
      const [stores, pending] = await Promise.all([
        TeamConnectionService.listMyStores(),
        TeamConnectionService.listPendingConnections(),
      ]);

      if (!active) return;
      setMyStores(stores);
      setPendingConnections(pending);
      setLoading(false);
    })();
    return () => {
      active = false;
    };
  }, [navigate]);

  const acceptConnection = useCallback(
    async (connectionId: string): Promise<boolean> => {
      const result = await TeamConnectionService.acceptConnection(connectionId);
      if (result.error) {
        addToast(result.error, 'error');
        return false;
      }
      addToast('Você agora faz parte da equipe!', 'success');
      load();
      return true;
    },
    [addToast, load],
  );

  const blockConnection = useCallback(
    async (connectionId: string): Promise<boolean> => {
      const result = await TeamConnectionService.blockConnection(connectionId);
      if (result.error) {
        addToast(result.error, 'error');
        return false;
      }
      addToast('Conexão removida.', 'success');
      load();
      return true;
    },
    [addToast, load],
  );

  return {
    myStores,
    pendingConnections,
    loading,
    acceptConnection,
    blockConnection,
    refresh: load,
  };
}

/**
 * useShiftInvites — hook de UI para convites de turno push (Slice 1, R5/R7/R8).
 *
 * Dois modos de uso:
 *   - useWorkerInvites: lista convites pendentes do worker + actions de resposta.
 *   - useCompanyInvites: lista convites enviados por job + action de convidar.
 *
 * Padrão do projeto: useState + useEffect + supabase direto (Art. 5 — sem React Query).
 */

import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../lib/supabase';
import { ShiftInviteService } from '../services/shiftInviteService';
import { useToast } from '../contexts/ToastContext';
import type { Application, InvitationResponse } from '../types';

// ---------------------------------------------------------------------------
// Hook para WORKER — aba "Convites"
// ---------------------------------------------------------------------------

export interface UseWorkerInvitesResult {
  /** Convites de turno pendentes (status='invited'). */
  pendingInvites: Application[];
  loading: boolean;
  /** ID do convite sendo processado (para loading state no botão). */
  respondingId: string | null;
  /** Aceitar ou recusar um convite. */
  respond: (applicationId: string, response: InvitationResponse) => Promise<boolean>;
  /** Recarregar convites. */
  refresh: () => void;
}

export function useWorkerInvites(): UseWorkerInvitesResult {
  const [pendingInvites, setPendingInvites] = useState<Application[]>([]);
  const [loading, setLoading] = useState(true);
  const [respondingId, setRespondingId] = useState<string | null>(null);
  const navigate = useNavigate();
  const { addToast } = useToast();

  const load = useCallback(async () => {
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) {
      navigate('/login');
      return;
    }

    setLoading(true);
    const invites = await ShiftInviteService.listPendingInvites();
    setPendingInvites(invites);
    setLoading(false);
  }, [navigate]);

  useEffect(() => {
    let active = true;
    void (async () => {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) {
        navigate('/login');
        return;
      }

      setLoading(true);
      const invites = await ShiftInviteService.listPendingInvites();
      if (!active) return;
      setPendingInvites(invites);
      setLoading(false);
    })();
    return () => {
      active = false;
    };
  }, [navigate]);

  const respond = useCallback(
    async (applicationId: string, response: InvitationResponse): Promise<boolean> => {
      setRespondingId(applicationId);
      const result = await ShiftInviteService.respondToInvite(applicationId, response);
      setRespondingId(null);

      if (result.error) {
        addToast(result.error, 'error');
        return false;
      }

      if (response === 'accepted') {
        addToast('Turno confirmado! Bom trabalho.', 'success');
      } else {
        addToast('Convite recusado.', 'info');
      }

      // Recarregar lista (o convite respondido some dos pendentes)
      load();
      return true;
    },
    [addToast, load],
  );

  return { pendingInvites, loading, respondingId, respond, refresh: load };
}

// ---------------------------------------------------------------------------
// Hook para EMPRESA — gerenciar convites por job
// ---------------------------------------------------------------------------

export interface UseCompanyInvitesResult {
  /** Convites enviados para o job. */
  invites: Application[];
  loading: boolean;
  /** ID do worker sendo convidado (para loading state). */
  invitingWorkerId: string | null;
  /** Convidar worker da equipe para o turno. */
  invite: (workerId: string, opts?: { expiresInHours?: number; message?: string }) => Promise<boolean>;
  /** Recarregar convites do job. */
  refresh: () => void;
}

export function useCompanyInvites(jobId: string): UseCompanyInvitesResult {
  const [invites, setInvites] = useState<Application[]>([]);
  const [loading, setLoading] = useState(true);
  const [invitingWorkerId, setInvitingWorkerId] = useState<string | null>(null);
  const navigate = useNavigate();
  const { addToast } = useToast();

  const load = useCallback(async () => {
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) {
      navigate('/login');
      return;
    }

    setLoading(true);
    const list = await ShiftInviteService.listInvitesByJob(jobId);
    setInvites(list);
    setLoading(false);
  }, [jobId, navigate]);

  useEffect(() => {
    let active = true;
    void (async () => {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) {
        navigate('/login');
        return;
      }

      setLoading(true);
      const list = await ShiftInviteService.listInvitesByJob(jobId);
      if (!active) return;
      setInvites(list);
      setLoading(false);
    })();
    return () => {
      active = false;
    };
  }, [jobId, navigate]);

  const invite = useCallback(
    async (
      workerId: string,
      opts: { expiresInHours?: number; message?: string } = {},
    ): Promise<boolean> => {
      setInvitingWorkerId(workerId);
      const result = await ShiftInviteService.inviteWorkerToShift(jobId, workerId, opts);
      setInvitingWorkerId(null);

      if (result.alreadyInvited) {
        addToast('Este freela já foi convidado para este turno.', 'info');
        return true;
      }
      if (result.error) {
        addToast(result.error, 'error');
        return false;
      }

      addToast('Convite enviado com sucesso!', 'success');
      load();
      return true;
    },
    [jobId, addToast, load],
  );

  return { invites, loading, invitingWorkerId, invite, refresh: load };
}
